#!/bin/bash\n\n# Backup script for production database\n# Creates automated backups of PostgreSQL database\n\nset -e\n\necho \"💾 Database Backup Script\"\necho \"\"\n\nif [ -z \"$DATABASE_URL\" ]; then\n    echo \"❌ DATABASE_URL environment variable not set\"\n    exit 1\nfi\n\nBACKUP_DIR=\"${1:-.}/backups\"\nTIMESTAMP=$(date +\"%Y%m%d_%H%M%S\")\nBACKUP_FILE=\"$BACKUP_DIR/backup_$TIMESTAMP.sql\"\n\n# Create backup directory if it doesn't exist\nmkdir -p \"$BACKUP_DIR\"\n\necho \"Creating backup...\"\necho \"Location: $BACKUP_FILE\"\necho \"\"\n\n# Create backup\npg_dump \"$DATABASE_URL\" > \"$BACKUP_FILE\"\n\necho \"✅ Backup created successfully\"\necho \"File size: $(du -h \"$BACKUP_FILE\" | cut -f1)\"\necho \"\"\n\n# Compress backup\ngzip \"$BACKUP_FILE\"\necho \"✅ Backup compressed\"\necho \"Compressed size: $(du -h \"$BACKUP_FILE.gz\" | cut -f1)\"\necho \"\"\n\n# Keep only last 7 backups\necho \"Cleaning up old backups...\"\nfind \"$BACKUP_DIR\" -name \"backup_*.sql.gz\" -mtime +7 -delete\necho \"✅ Old backups removed (kept last 7 days)\"\necho \"\"\n\necho \"Current backups:\"\nls -lh \"$BACKUP_DIR\"/backup_*.sql.gz | tail -5\necho \"\"\n\necho \"💾 Backup complete!\"\n"